	rawPacket.clear();
	if (m_DeviceOpened != true)
	{
		PCPP_LOG_ERROR("File device '" << m_FileName << "' not opened");
		return false;
	}
	snoop_packet_header_t snoop_packet_header;
	m_snoopFile.read((char*)&snoop_packet_header, sizeof(snoop_packet_header_t));
	if(!m_snoopFile) {
