	}
	size_t pad = be32toh(snoop_packet_header.packet_record_length) - (sizeof(snoop_packet_header_t) + be32toh(snoop_packet_header.included_length));
	m_snoopFile.ignore(pad);
	if(!m_snoopFile) {
		return false;
	}

	m_NumOfPacketsRead++;
	return true;
}

void SnoopFileReaderDevice::close()
{
	m_snoopFile.close();
